import{_ as a,o as t,c as s,a5 as o}from"./chunks/framework.C588jwcu.js";const _=JSON.parse('{"title":"Scene-based assets","description":"","frontmatter":{"title":"Scene-based assets","order":8},"headers":[],"relativePath":"en/latest/tutorial/core/scene-assets.md","filePath":"en/latest/tutorial/core/scene-assets.md","lastUpdated":1785683504000}'),n={name:"en/latest/tutorial/core/scene-assets.md"};function c(r,e,d,i,h,l){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="scene-based-assets" tabindex="-1">Scene-based assets <a class="header-anchor" href="#scene-based-assets" aria-label="Permalink to &quot;Scene-based assets&quot;">​</a></h1><p>Character and background entries now reference <code>PackedScene</code> resources. A scene may contain textures, video, Spine, Live2D, shaders, or custom nodes.</p><p>Character scenes should inherit <code>KND_CharacterSceneBase</code> and override <code>_apply_status(resolved_status_name, original_status_name)</code>; the system calls it through <code>apply_status(status_name)</code>. By default, <code>actor change</code> fades the character mount out, applies the state, and fades it in without duplicating the character scene. Story execution resumes after the transition finishes. See <a href="./../script/actor/actor-change-state.html">Change Actor State</a> for configuration. Optional stage motion belongs in a <code>KND_ActorMotionLayer</code> scene whose <code>AnimationPlayer</code> animation names match KS motion names.</p><p>Background scenes should inherit <code>KND_BackgroundSceneBase</code>. Assign the scene to <code>background_scene</code>; add uniquely named <code>KonadoCamera2D</code> nodes when camera commands are needed. Built-in transitions are handled by <code>KND_BackgroundTransitionLayer</code>.</p><p>Configure the corresponding <code>character_scene</code> or <code>background_scene</code> in the resource list. Keep node paths stable and make scene roots fill their parent when they are UI-based.</p>',5)])])}cons